mapper.select:
SELECT id, disease_code AS code, disease_name AS name, disease_icd AS icd, disease_category AS category FROM disease WHERE active = TRUE
AND (disease_code LIKE CONCAT('%', #{keyword}, '%') OR disease_name LIKE CONCAT('%', #{keyword}, '%') OR disease_icd LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY disease_code, id LIMIT #{limit}

SELECT id, tech_code AS code, tech_name AS name, tech_format AS format, tech_price AS price, tech_type AS type, department_id FROM medical_technology WHERE active = TRUE AND tech_type = #{type}
AND (tech_code LIKE CONCAT('%', #{keyword}, '%') OR tech_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY tech_code, id LIMIT #{limit}

SELECT id, drug_code AS code, drug_name AS name, drug_format AS format, drug_unit AS unit, drug_dosage AS dosage, drug_type AS type, drug_price AS price, manufacturer FROM drug_info WHERE active = TRUE
AND (drug_code LIKE CONCAT('%', #{keyword}, '%') OR drug_name LIKE CONCAT('%', #{keyword}, '%') OR mnemonic_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY drug_code, id LIMIT #{limit}
